// Extract user info and blog URL from webhook
const userId = $input.first().json.userId;
const blogUrl = $input.first().json.blogUrl;
const userName = $input.first().json.userName || 'Anonymous';

// Validate inputs
if (!userId || !blogUrl) {
  throw new Error('Missing required parameters: userId and blogUrl');
}

// Prepare crawl configuration
return {
  userId: userId,
  blogUrl: blogUrl,
  userName: userName,
  crawlId: `crawl_${userId}_${Date.now()}`,
  startTime: new Date().toISOString(),
  status: 'initiated'
};

// Parse HTML to extract blog posts
const html = $input.first().json.data || $input.first().binary?.data?.toString() || '';

// Simple regex-based extraction (in production, use proper HTML parser)
const postRegex = /<article[^>]*>([\s\S]*?)<\/article>/gi;
const titleRegex = /<h[1-3][^>]*>([^<]+)<\/h[1-3]>/i;
const linkRegex = /<a[^>]*href=["']([^"']+)["'][^>]*>/i;
const dateRegex = /<time[^>]*datetime=["']([^"']+)["'][^>]*>/i;

const posts = [];
let match;

while ((match = postRegex.exec(html)) !== null) {
  const articleHtml = match[1];

  const titleMatch = titleRegex.exec(articleHtml);
  const linkMatch = linkRegex.exec(articleHtml);
  const dateMatch = dateRegex.exec(articleHtml);

  if (titleMatch && linkMatch) {
    posts.push({
      title: titleMatch[1].trim(),
      url: linkMatch[1],
      date: dateMatch ? dateMatch[1] : null,
      content: articleHtml.substring(0, 500) // Preview
    });
  }
}

// If no posts found using article tags, try alternative selectors
if (posts.length === 0) {
  const h2Regex = /<h2[^>]*>([^<]+)<\/h2>/gi;
  const matches = [...html.matchAll(h2Regex)];
  matches.forEach((m, idx) => {
    posts.push({
      title: m[1].trim(),
      url: $json.blogUrl + '#post-' + idx,
      date: null,
      content: 'Extracted heading only'
    });
  });
}

return {
  userId: $json.userId,
  userName: $json.userName,
  blogUrl: $json.blogUrl,
  crawlId: $json.crawlId,
  postsFound: posts.length,
  posts: posts,
  crawledAt: new Date().toISOString(),
  status: 'completed'
};

// Process individual posts for storing in database
const posts = $json.posts || [];
const userId = $json.userId;
const crawlId = $json.crawlId;

return posts.map(post => ({
  userId: userId,
  crawlId: crawlId,
  title: post.title,
  url: post.url,
  publishDate: post.date,
  content: post.content,
  isNew: true
}));

